import 'dart:math';
import 'package:flutter/material.dart';

class QrScreen extends StatelessWidget { const QrScreen({super.key}); @override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(children:[Text('Мій QR',style:Theme.of(c).textTheme.headlineSmall!.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:18),Container(width:260,height:260,padding:22,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(24),boxShadow:[BoxShadow(color:Theme.of(c).colorScheme.shadow.withValues(alpha:.12),blurRadius:24)]),child:CustomPaint(painter:_QrPainter())),const SizedBox(height:18),const Chip(label:Text('ACTIVE • 05:00')),const SizedBox(height:12),FilledButton(onPressed:(){},child:const Text('Створити новий')),TextButton(onPressed:(){},child:const Text('Скасувати'))]))));}}
class _QrPainter extends CustomPainter { @override void paint(Canvas canvas,Size size){final p=Paint()..color=Colors.black;final r=Random(17);final n=17;final s=size.width/n;for(int y=0;y<n;y++){for(int x=0;x<n;x++){if(r.nextDouble()>.45)canvas.drawRect(Rect.fromLTWH(x*s,y*s,s-1,s-1),p);}}} @override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}
